    /** 该 URL 是否属于 TikTok 域（含其 CDN） */
    static boolean isTikTokUrl(String url){
        if(url == null) return false;
        String u = url.toLowerCase();
        return u.contains("tiktok.com") || u.contains("tiktokcdn") || u.contains("tiktokv")
            || u.contains("byteoversea") || u.contains("ibytedtos") || u.contains("muscdn");
    }

    /** 该 URL 是否属于 X / Twitter 域（含其 CDN 与解析镜像） */
    static boolean isXDomain(String url){
        return XParser.isXUrl(url)
            || (url != null && (url.contains("twimg.com") || url.contains("fxtwitter.com")));
    }

    /** 视频号凭据：读取元宝 Cookie（只存本机，不上传） */
    String ybCookie(){
        try{ return getSharedPreferences(SP, MODE_PRIVATE).getString(KEY_YB_CK, ""); }
        catch(Throwable t){ return ""; }
    }
    void ybCookieSave(String v){
        try{ getSharedPreferences(SP, MODE_PRIVATE).edit().putString(KEY_YB_CK, v == null ? "" : v.trim()).apply(); }
        catch(Throwable t){}
    }
    String ybCkLabel(){
        String c = ybCookie();
        if(c.length() == 0) return "可选 · 不配置也能解析视频号（拿到元数据+封面）";
        if(c.contains("hy_user") && c.contains("hy_token")) return "已保存 · 可选增强，不影响基本解析";
        return "格式不对 · 需含 hy_user 与 hy_token";
    }

    /** 微信视频号分享链接：weixin.qq.com/sph/xxx */
    static boolean isSphUrl(String u){
        if(u == null) return false;
        String s = u.toLowerCase(java.util.Locale.US);
        return s.contains("weixin.qq.com/sph/")
            || s.contains("channels.weixin.qq.com/finder-preview");
    }

    /** 微博：weibo.com / m.weibo.cn / video.weibo.com / t.cn / sinaimg.cn */
    static boolean isWeiboUrlSt(String u){
        return WeiboParser.isWeiboUrl(u);
    }

    /** 是否为海外平台链接（TikTok/X/YouTube/IG + CDN） */
    static boolean isOverseasUrl(String url){
        return isTikTokUrl(url) || isXDomain(url) || YtParser.isYtUrl(url)
            || InsParser.isInsUrl(url)
            || (url != null && (url.contains("googlevideo.com")
                || url.contains("videoplayback")));
    }

    /** 是否为「我们支持解析的平台」链接（含短链域名）。
     *  用途：用户贴了 GitHub / 随便一个网址时提前拦住，别拿去做 JSON 解析后报
     *  “Unexpected token 'B', Blocked by...” 这种莫名其妙的错。 */
    static boolean isSupportedParseUrl(String url){
        if(url == null || url.length() == 0) return false;
        String u = url.toLowerCase();
        // 磁力链接 / .torrent 直链（BT 引擎处理，不走平台解析）
        if(u.startsWith("magnet:") || u.contains(".torrent")) return true;
        // 抖音（含短链 v.douyin.com / iesdouyin / douyinpic 图床）
        if(u.contains("douyin.com") || u.contains("iesdouyin.com")
                || u.contains("amemv.com") || u.contains("snssdk.com")
                || u.contains("douyinpic.com") || u.contains("douyinvod.com")) return true;
        // 快手（含 short-v.kuaishou / kwaicdn）
        if(u.contains("kuaishou.com") || u.contains("chenzhongtech.com")
                || u.contains("kwaicdn.com") || u.contains("gifshow.com")) return true;
        // TikTok（含短链 vm.tiktok / vt.tiktok）
        if(isTikTokUrl(u)) return true;
        // X / Twitter
        if(isXDomain(u)) return true;
        // YouTube（含 youtu.be / googlevideo）
        if(YtParser.isYtUrl(u)) return true;
        // B站（含 b23.tv 短链）
        if(BiliParser.isBiliUrl(u) || u.contains("b23.tv") || u.contains("bilibili.com")
                || u.contains("bilivideo.com")) return true;
        // Instagram
        if(InsParser.isInsUrl(u)) return true;
        // 轻量平台合集（微视/AcFun/最右/皮皮虾/皮皮搞笑/好看/西瓜）
        if(MiscParser.isMiscUrl(u)) return true;
        // 今日头条（含 ixigua / toutiaocdn）
        if(ToutiaoParser.isToutiaoUrl(u)) return true;
        // 公众号（mp.weixin.qq.com/s…）
        if(WxMpParser.isWxMpUrl(u)) return true;
        // 豆包（doubao.com 分享页）
        if(DoubaoParser.isDoubaoUrl(u)) return true;
        // 小红书（含 xhslink 短链）
        if(XhsParser.isXhsUrl(u)) return true;
        // 微博（含 video.weibo.com / m.weibo.cn / t.cn / sinaimg）
        if(WeiboParser.isWeiboUrl(u)) return true;
        // 腾讯视频
        if(TxParser.isTxUrl(u)) return true;
        return false;
    }

