    // ================= 日志：强制记录 / 保留天数 =================

    /** 「强制记录」副标题 */
    String forceLogLabel(){
        boolean on = DypLog.isForceOn();
        if(on){
            return "已开启 · 调试日志开关关着也照写（帮我们抓现场用）";
        }
        return "已关闭 · 开关关着就不写文件，打开后即使日志开关关着也记录";
    }

    /** 切换强制记录 */
    void toggleForceLog(){
        boolean on = DypLog.isForceOn();
        DypLog.setForceOn(!on);
        showHintToast(!on
            ? "强制记录已开启：即使调试日志关着，功能日志也会写入文件"
            : "强制记录已关闭");
        buildSettingsPage();
    }

    /** 「日志保留天数」副标题 */
    String keepDaysLabel(){
        int d = DiagLog.keepDays();
        long sz = 0, dirSz = 0;
        int files = 0;
        try{
            java.io.File f = DiagLog.debugFile();
            if(f != null && f.exists()) sz = f.length();
            if(f != null && f.getParentFile() != null){
                java.io.File[] fs = f.getParentFile().listFiles();
                if(fs != null){
                    files = fs.length;
                    for(java.io.File x : fs) if(x != null && x.isFile()) dirSz += x.length();
                }
            }
        }catch(Throwable t){}
        String keep = (d <= 0) ? "不按时间清理" : ("保留 " + d + " 天");
        return keep + " · 单文件上限 100MB · 当前 "
                + InnerDownloader.sizeText(sz) + " / 目录 " + files + " 个共 "
                + InnerDownloader.sizeText(dirSz);
    }

    /** 选日志保留天数 */
    void showKeepDaysDialog(){
        curDark = isDarkMode();
        // 两步弹窗：先说明，再选。
        // 不能 setMessage + setSingleChoiceItems 混用 ——
        // message 会把列表挤掉，用户只能看到说明和取消按钮，
        // 选项一条都不显示（这个坑本项目踩过一次，用户明确要求禁止）。
        dypDlg()
            .setTitle("日志保留天数")
            .setMessage("超过天数的旧日志文件会被自动删除。\n\n"
                    + "另有两条固定规则，不受这里影响：\n"
                    + "· 单个日志文件超过 100MB → 截断保留后半段\n"
                    + "· logs 目录总大小超过 100MB → 从最旧的文件开始删\n\n"
                    + "debug.log / crash.log 是当前正在写的文件，不按天数删。\n\n"
                    + "当前：" + (DiagLog.keepDays() <= 0
                        ? "不按时间清理" : ("保留 " + DiagLog.keepDays() + " 天")))
            .setPositiveButton("选择天数", new android.content.DialogInterface.OnClickListener(){
                public void onClick(android.content.DialogInterface dd, int w){
                    showKeepDaysList();
                }
            })
            .setNegativeButton("关闭", null)
            .create().show();
    }

    /** 第二步：纯列表弹窗（不带 message，避免列表被挤没） */
    void showKeepDaysList(){
        final int[] vals = { 3, 7, 15, 30, 0 };
        String[] items = new String[vals.length];
        for(int i = 0; i < vals.length; i++){
            if(vals[i] == 0) items[i] = "不按时间清理（只受 100MB 上限约束）";
            else items[i] = "保留 " + vals[i] + " 天";
        }
        int cur = DiagLog.keepDays();
        int sel = 1;   // 默认 7 天
        for(int i = 0; i < vals.length; i++) if(vals[i] == cur) sel = i;
        dypDlg()
            .setTitle("选择日志保留天数")
            .setSingleChoiceItems(items, sel, new android.content.DialogInterface.OnClickListener(){
                public void onClick(android.content.DialogInterface dd, int which){
                    DiagLog.setKeepDays(vals[which]);
                    Log.i("DYP", "LOG_KEEP_DAYS set=" + vals[which]);
                    try{ dd.dismiss(); }catch(Throwable t){}
                    buildSettingsPage();
                    showHintToast(vals[which] == 0
                        ? "已关闭按天数清理" : ("日志保留 " + vals[which] + " 天"));
                }
            })
            .setNegativeButton("取消", null)
            .create().show();
    }

    // ================= 崩溃捕获 =================

    static boolean crashHandlerInstalled = false;

    /** 全局未捕获异常 → 写进崩溃日志，然后再交给系统默认处理（保证还能弹系统崩溃框） */
    void installCrashHandler(){
        if(crashHandlerInstalled) return;
        crashHandlerInstalled = true;
        final Thread.UncaughtExceptionHandler prev =
                Thread.getDefaultUncaughtExceptionHandler();
        Thread.setDefaultUncaughtExceptionHandler(new Thread.UncaughtExceptionHandler(){
            public void uncaughtException(Thread th, Throwable ex){
                try{
                    DiagLog.crash(DiagLog.M_APP,
                        "未捕获异常导致崩溃 | 线程=" + th.getName(), ex);
                }catch(Throwable t){}
                if(prev != null) prev.uncaughtException(th, ex);
            }
        });
DypLog.i("CRASH_HANDLER_INSTALLED");
    }

    // ================= 存储权限 =================
    static final int REQ_STORAGE = 1001;
    /** 选本地 .torrent 种子文件 */
    static final int REQ_TORRENT = 1002;
    /** 系统目录选择器（ACTION_OPEN_DOCUMENT_TREE） */
    static final int REQ_DIR_TREE = 1003;
    /** 本次系统目录选择要写进哪个 prefs key（选完在 onActivityResult 里用） */
    volatile String pendingDirKey = null;
    /** 本次选择的默认值（用来判断「选的就是默认目录」→ 存空值） */
    volatile String pendingDirDef = null;
    /** 本次启动是否已经自动申请过存储权限（避免每次回前台都弹） */
    volatile boolean permAskedThisLaunch = false;
    /** 本次启动是否已经弹过后台保活提示（避免 onResume 反复弹） */
    volatile boolean bgTipShown = false;

    /** 下载/保存前调用：没权限就申请，返回 false 表示已发起申请需等待 */
    boolean ensureStoragePerm(){
        if(AppInfo.hasStoragePerm(this)) return true;

        // 已被永久拒绝（Android 7 上系统不会再弹窗）→ 直接引导去设置页开
        if(AppInfo.storagePermBlocked(this)){
            DiagLog.w(DiagLog.M_PERM, "存储权限被永久拒绝 | API=" + android.os.Build.VERSION.SDK_INT
                + " | 引导用户去系统设置");
            showPermSettingsDialog();
            return false;
        }

        DiagLog.w(DiagLog.M_PERM, "缺少存储权限 | API=" + android.os.Build.VERSION.SDK_INT
            + " | 正在向用户申请 WRITE_EXTERNAL_STORAGE");
        // 标记「已申请过」，供 storagePermBlocked 判断永久拒绝
        try{
            getSharedPreferences(SP, MODE_PRIVATE).edit()
                .putBoolean("perm_storage_asked", true).apply();
        }catch(Throwable t){}
        try{
            requestPermissions(new String[]{
                android.Manifest.permission.WRITE_EXTERNAL_STORAGE,
                android.Manifest.permission.READ_EXTERNAL_STORAGE
            }, REQ_STORAGE);
        }catch(Throwable t){
            DiagLog.e(DiagLog.M_PERM, "申请存储权限失败 | " + t);
        }
        return false;
    }

    /** 权限被永久拒绝时的引导弹窗：教用户去系统设置里手动开启 */
    void showPermSettingsDialog(){
        StringBuilder m = new StringBuilder();
        m.append("本应用需要「存储权限」才能把文件保存到手机。\n\n");
        m.append("系统已经不再弹权限框了（之前被拒绝过），请手动开启：\n\n");
        m.append("1. 点下面「去设置」\n");
        m.append("2. 找到「存储」或「存储和相机」\n");
        m.append("3. 选择「允许」\n");
        m.append("4. 返回本应用重新点下载\n\n");
        m.append("如果找不到开关，也可以到：\n");
        m.append("系统设置 → 应用管理 → DY解析器 → 权限");
        dypDlg()
            .setTitle("需要存储权限")
            .setMessage(m.toString())
            .setPositiveButton("去设置", new android.content.DialogInterface.OnClickListener(){
                public void onClick(android.content.DialogInterface d, int w){
                    openAppSettings();
                }
            })
            .setNegativeButton("取消", null)
            .show();
    }

    /** 跳到本应用的系统设置页（权限/存储都在这里） */
    void openAppSettings(){
        try{
            android.content.Intent it = new android.content.Intent(
                    android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS);
            it.setData(android.net.Uri.parse("package:" + getPackageName()));
            startActivity(it);
        }catch(Throwable t){
            DypLog.i("OPEN_SETTINGS_ERR " + t);
            showHintToast("无法打开设置，请手动到系统设置里开启存储权限");
        }
    }

    @Override
    public void onRequestPermissionsResult(int code, String[] perms, int[] res){
        super.onRequestPermissionsResult(code, perms, res);
        if(code != REQ_STORAGE) return;
        boolean granted = res != null && res.length > 0
                && res[0] == android.content.pm.PackageManager.PERMISSION_GRANTED;
        if(granted){
            DiagLog.i(DiagLog.M_PERM, "存储权限已授予");
            showHintToast("存储权限已授予，可以正常下载了");
        }else{
            DiagLog.e(DiagLog.M_PERM, "存储权限被拒绝 | 下载将无法保存文件"
                + " | 建议=到系统设置 → 应用 → 本应用 → 权限 → 存储，手动打开");
            showStoragePermHelp();
        }
    }

    /** 权限被拒后的引导弹窗，说清楚为什么需要、去哪开 */
    void showStoragePermHelp(){
        curDark = isDarkMode();
        dypDlg()
            .setTitle("需要存储权限")
            .setMessage("下载文件必须能写入手机的 Download 目录，否则会出现"
                + "「能解析、能播放，但下载失败」的情况。\n\n"
                + "请按这个路径手动打开：\n"
                + "系统设置 → 应用管理 → DY解析器 → 权限 → 存储 → 允许\n\n"
                + "Android 11 及以上系统如果找不到「存储」权限项，"
                + "通常是系统已经默认允许，可以直接再试一次下载。")
            .setPositiveButton("去设置", new android.content.DialogInterface.OnClickListener(){
                public void onClick(android.content.DialogInterface d, int w){
                    try{
                        android.content.Intent it = new android.content.Intent(
                            android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS);
                        it.setData(android.net.Uri.parse("package:" + getPackageName()));
                        startActivity(it);
                    }catch(Throwable t){
                        showHintToast("请手动到系统设置里开启存储权限");
                    }
                }})
            .setNegativeButton("知道了", null)
            .show();
    }

